\begin{aligned}
    \textrm{If }P(A) \cap P(B) = 0 \textrm{ then:}\\
    P(A \cup B) &= P(A) + P(B) \\
    P(A \cap B) &= P(A) * P(B) \\
    P(A | B) &= P(A)
\end{aligned}

\begin{aligned}
    \textrm{If }P(A) \cap P(B) > 0 \textrm{ then:}\\
    P(A | B) &< P(A) \\
    P(A | B) &= \frac{P(A \cap B)}{P(B)} \\
    P(A \cap B) &= P(A) P(B|A)
\end{aligned}
